fg=lambda r,c: mat[r][c]!=0
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if fg(r,c) and (r,c) not in seen:
   q=deque([(r,c)]);seen.add((r,c)); comp=[]
   while q:
    p=q.popleft();comp.append(p)
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     nr,nc=p[0]+dr,p[1]+dc
     if 0<=nr<R and 0<=nc<C and fg(nr,nc) and (nr,nc) not in seen:
      seen.add((nr,nc));q.append((nr,nc))
   comps.append(comp)
